import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long X = r.nextLong(), Y = r.nextLong(), El = r.nextLong(), Er = r.nextLong();
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) { a[i] = r.nextLong(); total += a[i]; }
        BigInteger bx = BigInteger.valueOf(X), by = BigInteger.valueOf(Y), bl = BigInteger.valueOf(El), br = BigInteger.valueOf(Er);
        long prefix = 0;
        BigInteger ans = null;
        for (int left = 0; left <= n; left++) {
            int right = n - left;
            // The cost can exceed 64 bits.
            BigInteger cost = BigInteger.valueOf(prefix).multiply(bx)
                .add(BigInteger.valueOf(total - prefix).multiply(by))
                .add(BigInteger.valueOf(Math.max(0, left - right - 1)).multiply(bl))
                .add(BigInteger.valueOf(Math.max(0, right - left - 1)).multiply(br));
            if (ans == null || cost.compareTo(ans) < 0) ans = cost;
            if (left < n) prefix += a[left];
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

