	a := make([]int, n)
	total := 0
	for i := range a {
		a[i] = readInt()
		total += a[i]
	}
	prefix := 0
	var ans *big.Int
	cost, term, f := new(big.Int), new(big.Int), new(big.Int)
	for left := 0; left <= n; left++ {
		right := n - left
		// The cost can exceed 64 bits.
		cost.Mul(f.SetInt64(int64(prefix)), X)
		cost.Add(cost, term.Mul(f.SetInt64(int64(total-prefix)), Y))
		cost.Add(cost, term.Mul(f.SetInt64(int64(max(0, left-right-1))), El))
		cost.Add(cost, term.Mul(f.SetInt64(int64(max(0, right-left-1))), Er))
		if ans == nil {
			ans = new(big.Int).Set(cost)
		} else if cost.Cmp(ans) < 0 {
			ans.Set(cost)
		}
		if left < n {
			prefix += a[left]
		}
	}
	fmt.Println(ans.String())
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
